const NL = String.fromCharCode(10);
const LINK_NAME = 'Localization ticket';
const BASE = 'https://futuremedia.atlassian.net/browse/';
const ORDER = ['To Do', 'BLOCKED', 'PROD VERIFICATION'];
const MAX_CHARS = 3800;
const pages = $input.all();
let issues = [];
for (const p of pages) {
  const b = p.json || {};
  if (Array.isArray(b.issues)) { issues = issues.concat(b.issues); }
}
const lastPage = pages.length > 0 ? (pages[pages.length - 1].json || {}) : {};
const truncated = lastPage.isLast === false && !!lastPage.nextPageToken;
function clean(s) {
  const t = String(s || '');
  const a = t.indexOf('["');
  const b = t.indexOf('"]');
  if (a !== -1 && b > a) { return t.slice(a + 2, b); }
  return t;
}
function link(k) { return '<' + BASE + k + '|' + k + '>'; }
const rows = [];
const seen = {};
for (const iss of issues) {
  const f = iss.fields || {};
  const status = (f.status || {}).name || 'Unknown';
  if (ORDER.indexOf(status) === -1) { continue; }
  const links = f.issuelinks || [];
  for (const l of links) {
    const tn = l.type && l.type.name ? String(l.type.name) : '';
    if (tn.indexOf(LINK_NAME) === -1) { continue; }
    const other = l.inwardIssue || l.outwardIssue;
    if (!other || !other.fields || !other.fields.status) { continue; }
    const cat = other.fields.status.statusCategory || {};
    if (cat.key !== 'done') { continue; }
    const id = iss.key + '|' + other.key;
    if (seen[id]) { continue; }
    seen[id] = true;
    rows.push({ locKey: iss.key, locStatus: status, prodKey: other.key, summary: clean(f.summary) });
  }
}
if (rows.length === 0) { return []; }
rows.sort(function (a, b) { return a.locKey < b.locKey ? -1 : 1; });
const counts = [];
const chunks = [];
for (const st of ORDER) {
  const g = rows.filter(function (r) { return r.locStatus === st; });
  if (g.length === 0) { continue; }
  counts.push(g.length + ' ' + st);
  const lines = ['*' + st + ' (' + g.length + ')*'];
  for (const r of g) {
    lines.push('- ' + link(r.locKey) + '  <-  ' + link(r.prodKey) + '  ' + r.summary.slice(0, 80));
  }
  let buf = '';
  for (const line of lines) {
    if (buf.length + line.length + 1 > MAX_CHARS) { chunks.push(buf); buf = ''; }
    buf = buf.length > 0 ? buf + NL + line : line;
  }
  if (buf.length > 0) { chunks.push(buf); }
}
const head = [];
head.push('*Shipped but not localized* - the product ticket is Done, the localization ticket is not closed.');
head.push(rows.length + ' open: ' + counts.join(', ') + '. Details in thread.');
if (truncated) { head.push('_Jira returned more pages than were fetched - raise maxRequests on the fetch node._'); }
return [{ json: { summary: head.join(NL), chunks: chunks, openCount: rows.length } }];

const src = $('Find shipped but not localized').first().json.chunks || [];
const out = [];
for (const c of src) { out.push({ json: { chunk: c } }); }
return out;
